import { rmSync } from 'node:fs';
import { join } from 'node:path';

// Mirrors the docs/public entries ignored in .gitignore ("generated by docs/build/generate-ai.ts").
const AI_GENERATED = ['llms.txt', 'llms-full.txt', 'design.md', 'guide', 'components', 'hooks'];

export function prune(root, opts) {
  rmSync(join(root, '.github/workflows/template-e2e.yml'), { force: true });
  // Plinth's own GitHub Pages deploy; derived libraries decide on their own hosting.
  rmSync(join(root, '.github/workflows/docs.yml'), { force: true });
  // Output of `pnpm build:ai` (gitignored). A tree that was built before bootstrap still holds
  // Plinth-named copies, which would trip the sentinel scan; the next docs build regenerates them.
  for (const generated of AI_GENERATED) {
    rmSync(join(root, 'docs/public', generated), { recursive: true, force: true });
  }
  if (!opts.playground) {
    rmSync(join(root, 'playground'), { recursive: true, force: true });
  }
  if (opts.ci === 'none') {
    rmSync(join(root, '.github/workflows/ci.yml'), { force: true });
    rmSync(join(root, '.gitlab-ci.yml'), { force: true });
  } else if (opts.ci === 'gitlab') {
    rmSync(join(root, '.github/workflows/ci.yml'), { force: true });
  } else {
    rmSync(join(root, '.gitlab-ci.yml'), { force: true });
  }
}
